  "question": {
    "text": "In an adult population, what do the supplied two excerpts support about improvement at 8-week follow-up?",
    "population": "adults (no age range, setting or eligibility details supplied)",
    "timepoint": "8 weeks",
    "outcome": "improvement (measure and threshold not defined in either excerpt)"
  },
  "studies": [
    {
      "id": "S1",
